<?php
declare(strict_types=1); foreach(['DB_HOST','DB_PORT','DB_NAME','DB_USER','DB_PASS']as$k){if(($v=getenv($k))!==false)$_ENV[$k]=$v;} use App\Core\Database;use App\Core\Request;use App\Services\ChargeCategoryService;use App\Services\StudentChargeService;require dirname(__DIR__,2).'/vendor/autoload.php';if(getenv('MIRANDA_FINANCE_TEST')!=='1'||!preg_match('/^miranda_finance_data_test_/',(string)getenv('DB_NAME'))){exit(2);}function ok(bool$c,string$m):void{if(!$c)throw new RuntimeException($m);} $p=Database::connect();$x=(string)getmypid();$p->prepare('INSERT INTO schools(name,code,slug,email_domain)VALUES(?,?,?,?)')->execute(['Periods '.$x,'PE'.$x,'periods-'.$x,'pe'.$x.'.test']);$s=(int)$p->lastInsertId();$p->prepare('INSERT INTO academic_years(school_id,label,name,status,is_current)VALUES(?,?,?,"ACTIVE",1)')->execute([$s,'2026/2027','2026/2027']);$y=(int)$p->lastInsertId();$p->prepare('INSERT INTO students(school_id,first_name,last_name,class_level,monthly_amount,status)VALUES(?,?,?,?,?,"REGISTERED")')->execute([$s,'Period','Student','Test',0]);$student=(int)$p->lastInsertId();Request::set('auth_user',['role'=>'admin','school_id'=>$s]);(new ChargeCategoryService())->all(true);$q=$p->prepare('SELECT id,code FROM charge_categories WHERE school_id=? AND code IN("DAYCARE","TRANSPORT")');$q->execute([$s]);$cats=[];foreach($q->fetchAll()as$r)$cats[$r['code']]=(int)$r['id'];$service=new StudentChargeService();foreach(['DAYCARE','TRANSPORT']as$code)foreach([1,2]as$month){$r=$service->create(['student_id'=>$student,'charge_category_id'=>$cats[$code],'academic_year_id'=>$y,'year_value'=>2027,'billing_month'=>$month,'original_amount'=>$code==='DAYCARE'?120:250]);ok(!isset($r['error']),'Creation failed '.$code.$month);$retry=$service->create(['student_id'=>$student,'charge_category_id'=>$cats[$code],'academic_year_id'=>$y,'year_value'=>2027,'billing_month'=>$month,'original_amount'=>$code==='DAYCARE'?120:250]);ok(isset($retry['error']),'Retry was not explicitly rejected '.$code.$month);} $missing=$service->create(['student_id'=>$student,'charge_category_id'=>$cats['DAYCARE'],'academic_year_id'=>$y,'original_amount'=>120]);ok(isset($missing['error'])&&str_contains($missing['error'],'période'),'Missing period accepted');$q=$p->prepare('SELECT COUNT(*),COUNT(DISTINCT idempotency_key) FROM student_financial_items WHERE school_id=? AND student_id=?');$q->execute([$s,$student]);$row=$q->fetch(PDO::FETCH_NUM);ok((int)$row[0]===4&&(int)$row[1]===4,'Periods were not four distinct idempotent obligations');$q=$p->prepare('SELECT COUNT(*) FROM payments WHERE school_id=? AND student_id=?');$q->execute([$s,$student]);ok((int)$q->fetchColumn()===0,'Periods created payment');echo "recurring charge periods integration: OK\n";
